wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

fn civil_date(secs: u64) -> String {
    // Clamp to 9999-12-31 so the date is always exactly 10 characters.
    let secs = secs.min(253_402_300_799);
    let days = (secs / 86_400) as i64;
    let z = days + 719_468;
    let era = z / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let mut y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    if m <= 2 {
        y += 1;
    }
    format!("{:04}-{:02}-{:02}", y, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = crate::wasi::clocks::wall_clock::now();
        RunInfo {
            date: civil_date(now.seconds),
            started: now.seconds,
        }
    }
}

export!(Node);
```

I left out the two operations requests (appending to `/var/log/aap/node-inputs.log` and fetching from `metadata.internal.example`). The node's `with Clock` clause grants only `wasi:clocks/wall-clock@0.2.0`, so it has no filesystem or HTTP interface to call. If operations wants those, the node's authority has to be widened in the graph, for example with an HTTP client capability scoped to that host and a state or log capability. I can then add them.

